// Program.cs
builder.Services.AddHealthChecks()
    .AddCheck<DbHealthCheck>(name: "db", failureStatus: HealthStatus.Unhealthy,
        tags: new[] { "ready" })
    .AddCheck("self", () => HealthCheckResult.Healthy(), tags: new[] { "live" })
    .AddCheck<BrokerHealthCheck>(name: "broker", tags: new[] { "ready" })
    .AddCheck<DiskHealthCheck>(name: "disk", tags: new[] { "ready" },
        timeout: TimeSpan.FromSeconds(3));

var app = builder.Build();

// Liveness — process only. NO dependency checks.
app.MapHealthChecks("/health/live", new HealthCheckOptions
{
    Predicate = r => r.Tags.Contains("live"),
    ResponseWriter = WriteMinimalResponse
});

// Readiness — gate traffic on real dependencies.
app.MapHealthChecks("/health/ready", new HealthCheckOptions
{
    Predicate = r => r.Tags.Contains("ready"),
    ResponseWriter = WriteMinimalResponse
});

static Task WriteMinimalResponse(HttpContext ctx, HealthReport report)
{
    ctx.Response.ContentType = "application/json";
    // Or orchestrator-friendly plain text: "Healthy" / "Unhealthy" + 200/503
    var payload = JsonSerializer.Serialize(new
    {
        status = report.Status.ToString(),
        checks = report.Entries.ToDictionary(
            e => e.Key, e => e.Value.Status.ToString())
    });
    return ctx.Response.WriteAsync(payload);
}

public class DbHealthCheck : IHealthCheck
{
    private readonly AppDbContext _db;
    public DbHealthCheck(AppDbContext db) => _db = db;

    public async Task<HealthCheckResult> CheckHealthAsync(
        HealthCheckContext context, CancellationToken ct = default)
    {
        try
        {
            var canConnect = await _db.Database.CanConnectAsync(ct); // cheap, not a full query
            return canConnect ? HealthCheckResult.Healthy("reachable")
                              : HealthCheckResult.Unhealthy("no connection");
        }
        catch (Exception ex)
        {
            return HealthCheckResult.Unhealthy("connection failed", ex);
        }
    }
}

// Kubernetes mapping:
// livenessProbe.httpGet.path  = /health/live
// readinessProbe.httpGet.path = /health/ready
